import networkx as nx
import numpy as np

def generate_table(n):
    # Create an empty graph
    G = nx.Graph()

    # Add nodes for each cell in the n x n grid
    for i in range(n):
        for j in range(n):
            G.add_node((i, j))

    # Add edges between adjacent cells in the grid
    for i in range(n):
        for j in range(n):
            if j < n - 1:
                G.add_edge((i, j), (i, j + 1))
            if i < n - 1:
                G.add_edge((i, j), (i + 1, j))

    # Use a greedy algorithm to assign colors (I, M, O) to each node
    coloring = nx.coloring.greedy_color(G, strategy='largest_first')

    # Create a n x n table filled with the assigned colors
    table = np.zeros((n, n), dtype=str)
    for i in range(n):
        for j in range(n):
            if coloring[(i, j)] == 0:
                table[i, j] = 'I'
            elif coloring[(i, j)] == 1:
                table[i, j] = 'M'
            else:
                table[i, j] = 'O'

    return table

# Generate the table
table = generate_table(36)

# Print the table
for row in table:
    print(' '.join(row))
```

